function rect(x,y,w,h,{fill='#fff',dash=false,stroke='#333',radius=8}={}){body.push(`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${radius}" fill="${fill}" stroke="${stroke}" stroke-width="1.5"${dash?' stroke-dasharray="7 5"':''}/>`);}
function line(x1,y1,x2,y2,{arrow=false,dash=false}={}){body.push(`<path d="M${x1},${y1} L${x2},${y2}" fill="none" stroke="#444" stroke-width="1.7"${dash?' stroke-dasharray="6 5"':''}${arrow?' marker-end="url(#arrow)"':''}/>`);}
function wrap(str,width,size){const result=[];for(const part of String(str).split('\n')){let row='',units=0;for(const char of part){const v=/[\x00-\xff]/.test(char)?.58:1;if(row&&units+v>width/size){result.push(row);row='';units=0;}row+=char;units+=v;}result.push(row);}return result;}
function text(x,y,w,str,size=21,{bold=false,color='#222',gap=1.5}={}){const lines=wrap(str,w,size),height=lines.length*size*gap;body.push(`<text x="${x}" y="${y}" font-size="${size}" fill="${color}"${bold?' font-weight="700"':''}>${lines.map((s,i)=>`<tspan x="${x}" dy="${i?size*gap:0}">${xml(s)}</tspan>`).join('')}</text>`);bounds.push({x,y,w,bottom:y+(lines.length-1)*size*gap+size*.3,str});return height;}
function note(x,y,w,title,copy,{h=155,dash=false}={}){assert(72+(wrap(copy,w-40,19).length-1)*28.5+6<=h-10,'note text clipped: '+title);rect(x,y,w,h,{dash,fill:'#fafafa'});text(x+20,y+32,w-40,title,23,{bold:true});text(x+20,y+72,w-40,copy,19);}
