function chain(items,x,y,w,{h=126,gap=26,size=19}={}){const bw=(w-gap*(items.length-1))/items.length;assert(items.every(t=>65+(wrap(t,bw-28,size).length-1)*size*1.5+size*.3<=h-8),'chain text clipped: '+items.join(' / '));items.forEach((s,i)=>{const xx=x+i*(bw+gap);rect(xx,y,bw,h);text(xx+14,y+34,bw-28,String(i+1).padStart(2,'0'),16,{color:'#666'});text(xx+14,y+65,bw-28,s,size,{bold:true});if(i<items.length-1)line(xx+bw,y+h/2,xx+bw+gap-3,y+h/2,{arrow:true});});}

{const b=begin('00-inheritance','00 / 负责人包含专员职能，审核仍按原单分离','无需额外勾选专员岗，无需切回专员身份；专业工作台基本共用。',1200);profiles.forEach((p,i)=>{const y=188+i*103;rect(48,y,345,75);text(66,y+31,310,p.org+' · '+p.staff,23,{bold:true});line(394,y+38,454,y+38,{arrow:true});rect(462,y,390,75,{fill:'#f6f6f6'});text(480,y+31,354,p.lead+' = '+p.staff,22,{bold:true});text(480,y+58,354,'全部专业操作 ＋ 负责人管理动作',17);text(886,y+32,500,'相同导航：首页 / '+p.tab+' / 我的',23);text(886,y+62,500,'“我的”增加 '+p.team,18,{color:'#555'});});note(48,745,648,'能做专业操作，不等于能自审','本人制作、申请、登记或补证的原单，仍交另一位合格负责人独立核对。角色继承不改变实际人员回避。',{h:174});note(724,745,668,'能看团队，不等于能覆盖别人的工作','个人经办绑定本人责任或任务授权；团队负责人通过派单、交接或动作授权安排他人。其他专业权限不随之继承。',{h:174});note(48,950,1344,'最小审核人手必须满足','同一人可同时做专员和负责人，但不能在同一原单上同时经办与独立复核。缺少合格复核人时保持待复核，安排另一名本组织有权人员后继续。',{h:145});end(b);}
{const b=begin('01-home-navigation','01 / 首页一致，变化的是中间工作台和“我的”管理入口','下图是信息架构示意，品牌和公开内容不按岗位删减。',1220);phone(48,185,'首页','全部身份：内容一致','业务',['内容创作','方案设计','业务通用入口','工程通用入口','管理通用入口','培训与支持'],['品牌展示 / 加盟支持','通用内容、课程、工具'],'',{active:0});phone(408,185,'我的','负责人个人页','业务',['个人资料','消息与待办','我的绩效','身份与组织','学习与帮助','业务团队'],['本人信息与服务入口','＋ 本专业团队管理'],'',{active:2});text(796,220,580,'底部导航映射',25,{bold:true});let yy=266;for(const [label,nav]of [['业务员 / 业务负责人','首页 / 业务 / 我的'],['工程师 / 项目经理','首页 / 工程 / 我的'],['门店财务 / 财务负责人','首页 / 财务 / 我的'],['总部设计师 / 设计负责人','首页 / 设计 / 我的'],['总部财务 / 财务负责人','首页 / 财务 / 我的'],['门店老板 / 门店负责人','首页 / 业务 / 工程 / 管理 / 我的'],['未登录','首页 / 业务 / 工程 / 管理 / 我的']]){text(796,yy,580,label,19,{bold:true});text(796,yy+30,580,nav,19);yy+=78;}note(48,902,1344,'页面显示规则','工作台中无权的模块、表单、操作入口整体隐藏；有权限但暂无记录时显示明确空状态。通过旧链接进入无权页面时显示说明和返回本人工作台。首页通用入口不等于获得内部业务数据访问权。',{h:190});end(b);}
profiles.forEach((p,index)=>{const b=begin(String(index+2).padStart(2,'0')+'-'+p.key,`${String(index+2).padStart(2,'0')} / ${p.org} · ${p.staff}与${p.lead}`,`相同专业工具、相同底部导航。${p.lead}直接做专业操作，并多出负责人待办和“我的 → ${p.team}”。`,1390);phone(48,192,p.tab+'工作台',p.staff,p.tab,p.tools,p.tasks);phone(408,192,p.tab+'工作台',p.lead,p.tab,p.tools,p.tasks,p.extra[0]);text(785,221,604,'负责人增加的权限',25,{bold:true});p.extra.forEach((s,i)=>text(785,266+i*51,604,'＋ '+s,21));note(785,440,604,'“我的”中的管理入口',p.team+' → 团队任务、派单与责任交接、管理范围内待办。专业经办仍在同一工作台。',{h:153});note(785,620,604,'独立审核边界',p.avoid,{h:198});text(48,920,1344,'本岗位业务顺序（负责人经办时走同一条链）',26,{bold:true});chain(p.flow,48,957,1344,{h:137,size:19});text(48,1140,1344,'跨专业交接：交接业务原单、版本、责任人和状态；接收后不直接替另一专业确认完成。',21,{bold:true});p.handoffs.forEach((s,i)=>text(48,1187+i*42,1344,s,20));end(b);});
{const b=begin('07-governance','07 / 老板管授权与重大事项，门店负责人管日常经营','两者导航可以相同，默认都不自动拥有各专业经办和财务独立复核资格。',1330);phone(48,190,'管理工作台','老板','管理',['经营看板','经营目标','重大事项','授权政策','人员岗位','审计记录'],['授权与重大事项待决策','查看执行与经营结果'],'',{nav:['首页','业务','工程','管理','我的'],active:3});phone(408,190,'管理工作台','门店负责人','管理',['经营看板','经营执行','日常审批','交付协调','异常督办','服务反馈'],['授权内日常经营待办','跨业务、工程、财务协调'],'',{nav:['首页','业务','工程','管理','我的'],active:3});text(48,893,1344,'两者底部均为：首页 / 业务 / 工程 / 管理 / 我的；管理入口内按各自授权显示内容。',19,{color:'#555'});note(785,190,604,'当前代码中的真实区别','二者大部分经营查看、业务审批和责任交接权限相同。明确差别：老板能配置岗位和管理范围，门店负责人不能。',{h:190});note(785,410,604,'建议明确的授权边界','老板保留门店日常管理，并配置目标、岗位及审批策略；门店负责人执行受托范围的日常经营，超授权事项上送老板。两岗可同人兼任，具体额度待配置。',{h:220});note(785,660,604,'能审批业务，不替代专业复核','老板或门店负责人批准业务事项后，仍由财务实际登记与独立复核。若兼任专业岗位，按该岗位和任务权限经办，仍回避本人原单。',{h:195});rect(48,965,248,155);text(65,1007,214,'门店负责人提出或处理日常事项',22,{bold:true});line(296,1040,362,1040,{arrow:true});body.push('<path d="M365,1040 L470,975 L575,1040 L470,1105 Z" fill="white" stroke="#333" stroke-width="1.5"/>');text(409,1026,126,'在授权\n范围内？',21,{bold:true});rect(650,935,350,90);text(667,968,316,'是：门店负责人按原单办理',21,{bold:true});rect(650,1070,350,90);text(667,1103,316,'否：上送老板决策',21,{bold:true});body.push('<path d="M575,1040 H612 V980 H647 M575,1040 H612 V1115 H647" fill="none" stroke="#444" stroke-width="1.7" marker-end="url(#arrow)"/>');rect(1060,965,332,170);text(1077,1007,298,'各专业执行、独立核对',22,{bold:true});text(1077,1060,298,'门店负责人督办与反馈',19);body.push('<path d="M1000,980 H1025 V1050 H1057 M1000,1115 H1035 V1050 H1057" fill="none" stroke="#444" stroke-width="1.7" marker-end="url(#arrow)"/>');text(48,1235,1344,'经营看板 ≠ 全部原始凭证默认可见；敏感明细、导出和跨组织数据另设授权。此项为本次方案的待实施边界。',21);end(b);}

function laneBoard(key,title,sub,lanes,rows,links,{h=1450}={}){const b=begin(key,title,sub,h),x=48,y=190,gap=16,lw=(1344-gap*(lanes.length-1))/lanes.length,rh=(h-300)/rows.length,positions={};lanes.forEach((l,i)=>{rect(x+i*(lw+gap),y,lw,58,{fill:'#eee'});text(x+i*(lw+gap)+12,y+36,lw-24,l,21,{bold:true});line(x+i*(lw+gap)+lw/2,y+59,x+i*(lw+gap)+lw/2,h-70,{dash:true});});rows.forEach((row,ri)=>row.forEach(cell=>{const xx=x+cell.lane*(lw+gap),yy=y+83+ri*rh;rect(xx,yy,lw,rh-31,{fill:cell.gray?'#f2f2f2':'#fff'});text(xx+13,yy+30,lw-26,cell.title,20,{bold:true});text(xx+13,yy+66,lw-26,cell.copy,17);positions[cell.id]={x:xx,y:yy,w:lw,h:rh-31};}));for(const e of links){const a=positions[e[0]],c=positions[e[1]];assert(a&&c,e);const same=a.x===c.x;if(same)line(a.x+a.w/2,a.y+a.h,c.x+c.w/2,c.y-3,{arrow:true,dash:!!e[2]});else if(a.y===c.y&&Math.abs(a.x-c.x)<lw+gap+2)line(a.x+(a.x<c.x?a.w:0),a.y+a.h/2,c.x+(a.x<c.x?-3:c.w+3),c.y+c.h/2,{arrow:true,dash:!!e[2]});else if(a.y===c.y){const sy=a.y+a.h,rail=sy+14;body.push(`<path d="M${a.x+a.w/2},${sy} V${rail} H${c.x+c.w/2} V${sy+3}" fill="none" stroke="#444" stroke-width="1.5" marker-end="url(#arrow)"/>`);}else{const sx=a.x+a.w/2,sy=a.y+a.h,tx=c.x+c.w/2,ty=c.y-4;body.push(`<path d="M${sx},${sy} V${sy+14} H${tx} V${ty}" fill="none" stroke="#444" stroke-width="1.5"${e[2]?' stroke-dasharray="6 5"':''} marker-end="url(#arrow)"/>`);}}end(b);}
{const b=begin('08-whole-business','08 / 从内容创作到工程交付：跨专业流转总图','每步标注执行专业和岗位；负责人经办时走相同链，本人的独立审核必须交另一名合格人员。',1790);
const stages=[["阶段01 / 内容先行，形成有来源的客户",[["门店业务经办","内容创作与提交"],["另一业务负责人","本版内容独立审核"],["门店业务经办","按账号授权发布"],["业务负责人","线索分配与接受"],["门店业务经办","跟进核实、转客户"]]],["阶段02 / 首款双方独立生效，进入总部设计",[["门店业务及有权审核人","测量报价、真实合同、需求及服务约定"],["业务有权审核人","批准当前版本首款申请"],["门店财务 / 另一负责人","实际付款登记、独立复核"],["总部财务 / 另一负责人","查实实际到账、逐笔独立核算"],["总部设计负责人","受理需求、明确派单与协作动作"]]],["阶段03 / 本版成果完成，尾款分别核对后下发",[["总部设计经办 / 另一负责人","本版制作、提交、独立成果审核"],["门店业务 / 有权审核人","按服务单申请尾款并批准"],["门店财务 / 另一负责人","尾款实付登记、独立复核"],["总部财务 / 另一负责人","尾款实际查收、独立核算"],["获任务授权的设计人员","本版已审、双方款项条件满足后下发"]]],["阶段04 / 客户真实签认与施工图审核，明确工程责任",[["门店业务 / 另一负责人","登记客户真实签认、独立核验"],["门店业务经办","按确认成果提交本版施工图"],["总部独立专业审核人","核验本版施工图；退回需改版重审"],["门店业务经办","齐备资料、审核、合同与原单移交"],["项目经理 / 实际工程师","明确派单、本人核对接收；不自动开工"]]],["阶段05 / 执行、交付独立核验、归档",[["工程经办人员","六项准备完成、记录实际开工"],["工程经办人员","材料实收、施工节点、短缺补发与整改复验"],["工程经办人员","真实客户交付签认、本次竣工资料"],["另一有权项目经理","独立核验；退回后沿原交付补证"],["工程经办人员","核验通过后归档；施工资料锁定"]]]];
stages.forEach(([title,items],index)=>{const y=190+index*260;text(48,y,1344,title,25,{bold:true});const gap=26,w=(1344-gap*4)/5;items.forEach(([role,action],i)=>{const x=48+i*(w+gap);rect(x,y+30,w,180);text(x+14,y+60,w-28,role,17,{color:'#555'});line(x+12,y+78,x+w-12,y+78);text(x+14,y+110,w-28,action,21,{bold:true});if(i<4)line(x+w,y+120,x+w+gap-3,y+120,{arrow:true});});});
note(48,1530,1344,'工程执行中的财务支线，继续按原单独立办理','采购事项由有权人员业务批准 → 财务实际付款 → 另一负责人复核；工程收款线索 → 本组织查实到账 → 另一负责人独立核算。工程归档不等于财务结清，未结应收应付和补证继续流转。',{h:175});end(b);}


{const b=begin('09-independent-finance','09 / 门店与总部独立记账、独立复核','负责人可以登记，但原笔经办与独立复核必须由不同实际人员承担。',1320);text(48,205,1344,'门店账簿：付款申请、实际付款、有效已付',27,{bold:true});chain(['业务有权人员批准原申请','财务 A 登记线下实际付款','财务负责人 B 独立付款复核','门店有效已付；生成总部待查收'],48,243,1344,{h:151,size:21});text(48,445,1344,'总部账簿：实际到账、独立核算、设计服务款条件',27,{bold:true});chain(['总部待查收：尚不是到账','财务 C 核实银行并分笔登记','财务负责人 D 独立核算','总部有效到账；回传原服务单'],48,485,1344,{h:151,size:21});body.push('<path d="M1234,394 V416 H28 V561 H45" fill="none" stroke="#444" stroke-width="1.7" marker-end="url(#arrow)"/>');note(48,699,648,'按实际人员回避，不能换账号绕过','A 不能是 B；C 不能是 D。独立复核还要排除该原单申请、审批、历史补证人员，以及本往来链对侧相关参与人。',{h:195});note(724,699,668,'专业能力继承，不改变原单独立性','财务负责人可作为 A 或 C 亲自登记；此笔必须安排另一名本组织合格负责人复核。不能让专员、老板或门店负责人代替独立复核。',{h:195});note(48,929,1344,'两端如何衔接','用组织、订单、原付款编号、阶段、分笔金额、到账匹配和版本关联。允许2000＋3000分笔查收，各笔分别核算；重复流水拦截、超收待分配和结果未知占用，均保留原单处理。',{h:193});end(b);}
{const b=begin('10-return-evidence','10 / 退回补证必须沿原单闭环','申请补证、付款补证、跨组织索证和工程交付补证共用“原单 + 版本 + 当前经办 + 独立复核”的原则。',1370);chain(['独立审核人退回并写明缺项','原单当前经办补齐证据','原金额、流水、历史与版本保留','重新进入待核对，另一人独立核对','通过才生效；证据任务才关闭'],48,210,1344,{h:183,size:21});text(48,465,1344,'跨组织两轮补证：回复不等于入账，也不等于独立复核完成',27,{bold:true});chain(['本方发起：绑定原单与缺项','对方当前经办回复原笔证据','仍不足：退回并升级请求版本','对方第二轮补齐证据并回复','本方经办把本轮回复补入原单','本方另一负责人独立核对后关闭'],48,505,1344,{h:185,size:21});line(1291,690,1291,735,{dash:true});line(1291,735,606,735,{dash:true});line(606,735,606,693,{arrow:true,dash:true});text(610,773,650,'仍缺对方证据 → 回到本轮退回 / 回复',18,{color:'#555'});note(48,838,648,'经办离岗或需换人','由有权负责人正式交接当前补证责任。原申请、原登记人和所有历史补证人员保留；旧经办失去办理权，新经办在原单继续。',{h:205});note(724,838,668,'金额或业务事实变化','补证不能直接改原金额、原流水和原合同。需要变化时走正式更正、变更或退款审批，再由独立人员核对。',{h:205});text(48,1123,1344,'关闭条件：当前轮证据已绑定原单 ＋ 当前原单版本满足要求 ＋ 独立复核通过 ＋ 原业务状态已回写。',25,{bold:true});end(b);}
{const b=begin('11-refund-correction','11 / 退款回流与金额更正分开走','退款涉及实际资金返回；更正形成原收款修订。两者均不删除原始记录。',1390);text(48,205,1344,'退款：例为总部退回门店的原设计服务款',28,{bold:true});chain(['财务 A 提交原退款申请','有权业务人员批准；可退回补证','另一财务 B 登记实际退款','财务负责人 C 独立复核','门店另行查收，由他人独立核算'],48,245,1344,{h:194,size:20});note(48,478,1344,'退款角色边界','财务负责人也可申请或执行退款；但申请、批准、执行和独立复核须符合该原单的人员分离。设计负责人仅在明确授权的设计服务业务政策内审批，不能因此登记退款或作财务核算。',{h:176});text(48,724,1344,'更正：原收款不覆盖，形成可追溯修订',28,{bold:true});chain(['财务人员提出原收款更正','说明差额与完整原渠道依据','另一合格财务负责人独立复核','形成原单金额修订并留原始值','相关余额与业务条件重新计算'],48,767,1344,{h:194,size:20});note(48,1006,1344,'退回与状态约束','申请退回后由当前经办补原申请，不换金额。更正通过前原有效金额保持；未知退款结果保留占用，不把“仍待核实”当作“确认未退款”。实际退款与门店实际到账也分别成账。',{h:199});end(b);}
{const b=begin('12-engineering-delivery','12 / 工程接收、执行、交付与财务收尾','项目经理继承工程师完整操作；他亲自经办的工程交付仍由另一位有权项目经理独立核验。',1450);chain(['业务移交齐备资料与原审核','项目经理明确派单，工程师接收','六项准备完成，记录实际开工','材料实收、施工节点与验收','整改复验、短缺补发闭环'],48,210,1344,{h:184,size:20});text(48,464,1344,'交付归档链',28,{bold:true});chain(['工程经办登记真实交付与客户签认','另一有权项目经理独立核验本版资料','核验通过 → 工程归档，施工资料锁定'],48,505,1344,{h:140,size:21});rect(490,695,460,76,{dash:true});text(510,727,420,'退回：原经办沿原交付补齐证据',21,{bold:true});line(720,645,720,692,{arrow:true,dash:true});body.push('<path d="M490,733 V575 H502" fill="none" stroke="#444" stroke-width="1.7" stroke-dasharray="6 5" marker-end="url(#arrow)"/>');text(170,742,280,'补证后重新送独立核验',18,{color:'#555'});note(48,813,648,'项目经理亲自做专业工作','可承接本人明确负责的工程，记录现场、材料、验收、交付及补证；不用切换工程师身份。本人交付不能本人核验。',{h:197});note(724,813,668,'归档与财务分别关闭','工程归档不自动代表合同已收齐、采购已付清或最终利润已确认。未结应收应付与补证责任继续流转，原施工档案保持锁定。',{h:197});text(48,1080,1344,'跨专业异常',26,{bold:true});text(48,1127,1344,'图纸或范围变化 → 业务变更审批与客户真实签认 → 总部设计新版本与独立审核 → 补充移交 → 工程确认接收。',23);text(48,1221,1344,'采购付款与客户工程款 → 工程提供业务原单或线索 → 本组织财务查实登记 → 另一财务负责人独立核对 → 回写原项目。',23);end(b);}
{const b=begin('13-deferred-headquarters','13 / 总部运营与总部老板：后续岗位规划','仅为完整组织 IA 附录；不新增本轮小程序页面，也不把该导航写成已上线。',1200);model.deferred.forEach((r,i)=>note(48+i*454,200,434,r.organization+' · '+r.role,'规划导航：'+r.nav.join(' / ')+'\n\n'+r.flow,{h:370,dash:true}));text(48,651,1344,'运营与门店业务的衔接',28,{bold:true});chain(['总部运营制作活动与公共素材','另一有权运营负责人独立审核','按门店范围下发运营任务','门店业务按本地账号授权制作发布','线索进入门店跟进与本地客户链'],48,696,1344,{h:190,size:20});note(48,949,1344,'与当前范围保持一致','本轮主线仍是加盟商业务流程，以及总部设计和财务。总部运营专员、运营负责人及总部老板的页面、具体动作和最终导航，留待后续范围实施。',{h:157,dash:true});end(b);}

const cards=boards.map(b=>`<section id="${b.key}"><header><h2>${xml(b.title)}</h2><p>${xml(b.sub)}</p><div class="downloads"><a href="${b.key}.svg" target="_blank">查看矢量大图</a><a href="${b.key}.svg" download>下载 SVG</a><a href="${b.key}.png" download>下载 PNG</a></div></header><a class="drawing" href="${b.key}.svg" target="_blank"><img src="${b.key}.svg" alt="${xml(b.title)}" loading="lazy"></a><details><summary>文字说明</summary>${b.labels.map(s=>'<p>'+xml(s).replace(/\n/g,'<br>')+'</p>').join('')}</details></section>`).join('');
const html=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>岗位继承、工作台与跨专业流转 IA 线稿</title><style>body{margin:0;color:#222;background:#ececec;font:16px/1.7 "Microsoft YaHei",sans-serif}main{max-width:1500px;margin:auto;padding:30px 28px}h1{font-size:29px;margin-bottom:12px}h2{font-size:23px;margin:0}h3{font-size:19px}.intro,section{background:#fff;padding:28px;margin:0 0 28px;border:1px solid #bbb}p{margin:10px 0}.status{border-left:4px solid #333;padding:12px 18px;background:#f5f5f5}.toc{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:8px}a{color:#333;text-underline-offset:4px}.drawing{display:block;margin-top:20px}.drawing img{display:block;width:100%;height:auto}.downloads{display:flex;gap:22px;flex-wrap:wrap;margin-top:12px}table{border-collapse:collapse;width:100%;font-size:15px}td,th{padding:12px;border:1px solid #bbb;text-align:left;vertical-align:top}th{background:#f3f3f3}.tablewrap{overflow:auto}details{margin-top:18px}summary{cursor:pointer}button{font:inherit;background:white;border:1px solid #777;padding:8px 18px;cursor:pointer}.top{display:flex;justify-content:space-between;gap:20px;align-items:start;flex-wrap:wrap}.small{font-size:14px;color:#666}.rolelist{columns:2;column-gap:36px}.rolelist p{break-inside:avoid}.back{display:block;margin:8px 0 18px}@media(max-width:700px){main{padding:14px}.intro,section{padding:16px}.rolelist{columns:1}h1{font-size:25px}}@media print{body{background:white}main{padding:0;max-width:none}.intro,section{border:0;padding:0;break-before:page}.intro{break-before:auto}.toc,.downloads,details,button,.back{display:none}.drawing{margin:0}h2{font-size:17px}.drawing img{max-height:85vh;object-fit:contain}a{color:black;text-decoration:none}}</style></head><body><main id="top"><div class="intro"><div class="top"><div><p class="small">2026-10-19 · 新岗位继承规则 · 低保真方案</p><h1>岗位、专业工作台与跨专业流转 IA 线稿</h1></div><button type="button" onclick="window.print()">打印 / 另存为 PDF</button></div><p class="status"><strong>负责人 = 本专业专员的完整操作 + 本专业管理权限。</strong>本轮绘制方案，未修改小程序业务代码；此前测试报告对应旧岗位规则，不能当作这套新规则已实现。</p><p>负责人无需另选专员岗或切换身份；两者工作台和底部导航大部分一致。负责人在同一工作台接收负责人待办，在“我的”增加团队管理。继承只限本专业，实际经办仍须落在本人责任或任务授权范围。</p><p><strong>独立性不变：</strong>本人制作、申请、登记或补证不能本人独立审核。换账号、兼岗、跨组织均按实际人员识别；缺少合格复核人时保持待核。</p><h3>老板和门店负责人的区别</h3><p>当前代码中，二者多数日常管理权限相同；明确差别是老板可以配置岗位和管理范围，门店负责人不能。建议细化为下表；重大事项和额度分级属于待实施设计。</p><div class="tablewrap"><table><tr><th>事项</th><th>老板</th><th>门店负责人</th></tr><tr><td>核心职责</td><td>经营目标、组织授权、经营政策与重大事项决策</td><td>受托范围内的日常经营、执行、交付与跨专业协调</td></tr><tr><td>人员岗位与管理范围配置</td><td>本组织配置与授权；重大授权变更留痕</td><td>不直接配置；提出需求，由老板授权</td></tr><tr><td>业务审批</td><td>按组织策略处理重大或超授权事项</td><td>按授予的事项与额度处理普通日常事项</td></tr><tr><td>专业经办</td><td colspan="2">两者均不自动获得所有专业操作；需有对应专业岗位资格及任务范围。专业负责人继承专员，与经营管理身份不是同一件事。</td></tr><tr><td>财务复核</td><td colspan="2">管理身份不能代替独立财务复核；即使兼任财务负责人，仍回避本人及不满足独立性的原单。</td></tr><tr><td>导航</td><td colspan="2">首页 / 业务 / 工程 / 管理 / 我的；相同导航不等于完全相同的按钮和数据范围。</td></tr></table></div><p>老板保留门店日常管理能力，并可把受托事项交给门店负责人；老板亲自经营时可由同一人兼任两岗，无需创建两个不同人员。委托职业店长经营时再分人。财务原单仍由另一名合格实际人员独立复核。</p><h3>阅读顺序</h3><nav class="toc" aria-label="IA 图纸目录">${boards.map(b=>`<a href="#${b.key}">${xml(b.title)}</a>`).join('')}</nav><p class="small">实线表示流转；虚线表示退回或后续规划；“＋”表示负责人增加。点击图纸打开原尺寸矢量大图，每张也可下载 PNG。</p></div>${cards}<section id="role-index"><h2>12个当前岗位逐项索引</h2><div class="rolelist">${roles.map(r=>'<p><strong>'+xml(r.organization+' · '+r.role)+'</strong><br>导航：'+xml(r.nav.join(' / '))+'<br>'+xml(r.inherits?'继承 '+r.inherits+' 全部经办操作；增加 '+r.adds.join('、'):r.base.join('、'))+'<br>'+xml(r.dataScope||r.boundary)+'</p>').join('')}</div></section><section id="code-gap"><h2>现有代码需要按新规则调整的位置</h2><p>本次只绘制与梳理，以下尚未修改；此前“负责人不能做专员操作”的测试断言需要同步更新。</p><div class="tablewrap"><table><tr><th>调整项</th><th>现有位置</th><th>目标行为</th></tr>${model.codeGaps.map(r=>'<tr>'+r.map(x=>'<td>'+xml(x)+'</td>').join('')+'</tr>').join('')}</table></div><p>实施后的重点验收：只配置负责人一个岗位也能完成专业经办；本人不能自审；另一合格负责人可核；专员不能派单或独立复核；不同专业不自动继承；门店与总部账簿、流水和证据分别隔离。</p><p><a href="岗位继承与跨专业流转IA方案.json">结构化岗位与流转方案</a> · <a href="IA图纸目录.json">图纸目录</a> · <a href="#top">返回目录</a></p></section></main><script>document.querySelectorAll('section[id]').forEach(s=>{const a=document.createElement('a');a.href='#top';a.className='back';a.textContent='↑ 返回目录';s.prepend(a);});</script></body></html>`;
const filename='岗位继承与跨专业业务流转IA线稿.html';fs.writeFileSync(path.join(out,filename),html);fs.writeFileSync(path.join(out,'IA图纸目录.json'),JSON.stringify({date:'2026-10-19',scope:model.scope,roleCount:roles.length,boardCount:boards.length,boards:boards.map(({svg,labels,...b})=>b)},null,2));
console.log(JSON.stringify({file:path.join(out,filename),boards:boards.length,roles:roles.length,status:model.status}));

(async()=>{const sharp=require("C:/Users/Administrator/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/sharp");for(const b of boards)await sharp(path.join(out,b.key+".svg")).png().toFile(path.join(out,b.key+".png"));for(let part=0;part<4;part++){const items=boards.slice(part*4,part*4+4),tiles=[];for(let i=0;i<items.length;i++){const input=await sharp(path.join(out,items[i].key+".png")).resize({width:510,height:655,fit:"contain",background:"#fff"}).png().toBuffer();tiles.push({input,left:(i%2)*530+10,top:Math.floor(i/2)*675+10});}await sharp({create:{width:1060,height:Math.ceil(items.length/2)*675,channels:3,background:"#ddd"}}).composite(tiles).png().toFile(path.join(out,"qa-contact-"+(part+1)+".png"));}console.log("Rendered 14 boards and four QA sheets");})().catch(e=>{console.error(e.stack);process.exitCode=1});
